    "botanicalDescription": "ক্যারিকাসি (Caricaceae) পরিবারের নরম কাণ্ডের ছোট বৃক্ষের বেরি জাতীয় ফল। কাঁচা অবস্থায় সবুজ ও পাকা অবস্থায় হলুদাভ কমলা রঙের শাঁসযুক্ত হয়। মাঝখানে ফাঁপা গহ্বরে অসংখ্য কালো বীজ থাকে।",
    "availabilityAndSeasonality": "সারা বছরই বাংলাদেশে পেঁপের জোগান থাকে। দেশের সব জেলায় গৃহস্থালী ও বাণিজ্যিক পর্যায়ে পেঁপে চাষ হয়। রাজশাহী, যশোর ও নরসিংদীতে ব্যাপক ফলন হয়।",
