    "excessConsumption": "অতিরিক্ত পেঁপে খেলে এতে থাকা বিটা ক্যারোটিনের কারণে ত্বকে সাময়িকভাবে হালকা হলুদাভ আভা (ক্যারোটেনোডার্মিয়া) দেখা দিতে পারে, যা ক্ষতিকর নয় এবং খাওয়া কমালে স্বাভাবিক হয়।",
