        "answer": "না, এটি একটি অবৈজ্ঞানিক পৌরাণিক ধারণা। তবে দুধের সাথে অম্লীয় আনারস মিশলে দুধ কেটে ছানা হতে পারে এবং সংবেদনশীল পেটে বদহজম হতে পারে, বিষক্রিয়া নয়।"
