    "botanicalDescription": "মিরটাসি (Myrtaceae) পরিবারের চিরসবুজ ক্ষুদ্রাকার বৃক্ষের বেরি জাতীয় ফল। ত্বক হালকা সবুজ বা হলুদাভ, ভেতরের শাঁস সাদা বা হালকা গোলাপি এবং শক্ত বীজে পূর্ণ থাকে।",
