    "introduction": "কমলা শীতকালের অত্যন্ত প্রিয় একটি রসালো সাইট্রাস ফল, যার সহজে ছাড়ানো যায় এমন খোসা এবং মিষ্টি-অম্লীয় স্বাদ সবার পছন্দ।",
    "botanicalDescription": "রুটেসি (Rutaceae) পরিবারের ছোট চিরসবুজ বৃক্ষের হেসপেরিডিয়াম জাতীয় ফল। খোসা ঢিলেঢালাভাবে শাঁসের সাথে লেগে থাকে এবং সহজেই হাত দিয়ে ছাড়ানো যায়।",
    "availabilityAndSeasonality": "বাংলাদেশে নভেম্বর থেকে জানুয়ারি মাস পর্যন্ত কমলার মূল মৌসুম। সিলেট, মৌলভীবাজার ও পঞ্চগড়ে স্থানীয়ভাবে কমলার চাষ হচ্ছে; এছাড়া শীত ও সারা বছর ভারত, মিশর ও দক্ষিণ আফ্রিকা থেকে প্রচুর আমদানি করা হয়।",
