    "availabilityAndSeasonality": "বাংলাদেশে স্থানীয় 'বারি মাল্টা-১' সেপ্টেম্বর থেকে নভেম্বর মাসে পাকে। দেশের বিভিন্ন জেলায় এখন ব্যাপকভাবে মাল্টা বাগান গড়ে উঠেছে; এছাড়া সারা বছর বাজারে মিশর ও দক্ষিণ আফ্রিকার মিষ্টি মাল্টা পাওয়া যায়।",
