    "botanicalDescription": "র‍্যামনাসি (Rhamnaceae) পরিবারের কাঁটাযুক্ত ছোট বৃক্ষের ড্রুপ জাতীয় ফল। গোলাকার বা ডিম্বাকৃতির মসৃণ ত্বক, ভেতরে সাদাটে মুচমুচে শাঁস ও শক্ত খাঁজকাটা আঁটি থাকে।",
    "availabilityAndSeasonality": "বাংলাদেশে জানুয়ারি থেকে মার্চ (পৌষ থেকে ফাল্গুন) মাসে বোরইয়ের মূল মৌসুম। রাজশাহী, নাটোর, চুয়াডাঙ্গা ও মেহেরপুরে আপেল কুল, বাউকুল ও থাই কুলের বাণিজ্যিক চাষ হয়।",
