    "buyingAndStorage": "দাগহীন, শক্ত এবং উজ্জ্বল ত্বকের বরই কিনুন। সাধারণ তাপমাত্রায় ৩-৪ দিন এবং রেফ্রিজারেটরে ১-২ সপ্তাহ পর্যন্ত ভালো থাকে। শুকিয়ে দীর্ঘদিন রাখা যায়।",
