    "buyingAndStorage": "দাগহীন, শক্ত এবং মসৃণ উজ্জ্বল সবুজ জলপাই কিনুন। রেফ্রিজারেটরে ২-৩ সপ্তাহ ভালো থাকে এবং আচার বানিয়ে তেল ডুবিয়ে রাখলে ১-২ বছর অনায়াসে রাখা যায়।",
