    "excessConsumption": "একসাথে অনেকগুলো খেজুর খেলে দ্রুত ওজন বৃদ্ধি পেতে পারে এবং রক্তের গ্লুকোজ বেড়ে যেতে পারে।",
    "buyingAndStorage": "পোকা ও ছত্রাকহীন, অতিরিক্ত কৃত্রিম সিরাপে আঠালো নয় এমন তাজা খেজুর নির্বাচন করুন। বায়ুরোধী পাত্রে সাধারণ তাপমাত্রায় কয়েক মাস এবং রেফ্রিজারেটরে ১ বছর পর্যন্ত ভালো থাকে।",
