    "availabilityAndSeasonality": "বাংলাদেশে মে থেকে নভেম্বর মাস পর্যন্ত দফায় দফায় ড্রাগন ফলের ফলন পাওয়া যায়। নাটোর, ঝিনাইদহ, চুয়াডাঙ্গা, পাবনা ও ময়মনসিংহে বাণিজ্যিকভাবে প্রচুর লাল ও সাদা ড্রাগন ফল উৎপন্ন হয়।",
