export function getFruitBySlug(slug: string): Fruit | undefined {
  return fruits.find((f) => f.slug === slug);
}

export function getRelatedFruits(current: Fruit, count = 4): Fruit[] {
  const currentTags = new Set([...current.seasonTags, ...current.fruitGroupTags]);
  return fruits
    .filter((f) => f.slug !== current.slug)
    .map((f) => {
      let score = 0;
      f.seasonTags.forEach((t) => { if (currentTags.has(t)) score += 2; });
      f.fruitGroupTags.forEach((t) => { if (currentTags.has(t)) score += 3; });
      f.availabilityTags.forEach((t) => { if (current.availabilityTags.includes(t)) score += 1; });
      return { fruit: f, score };
    })
    .sort((a, b) => b.score - a.score)
    .slice(0, count)
    .map((item) => item.fruit);
}
